import Foundation
struct Ingredient:Codable{let name:String;let quantity:Double;let unit:String}
struct Recipe:Codable{let title:String;let servings:Double;let ingredients:[Ingredient]}
enum Invalid:Error{case input}
func scale(_ r:Recipe,_ servings:Double)throws->Recipe{guard r.servings.isFinite,r.servings>0,servings.isFinite,servings>0,servings<=10000,!r.title.isEmpty,!r.ingredients.isEmpty,r.ingredients.allSatisfy({!$0.name.isEmpty && $0.quantity.isFinite && $0.quantity>=0})else{throw Invalid.input};let ratio=servings/r.servings;let ingredients=r.ingredients.map{Ingredient(name:$0.name,quantity:$0.quantity*ratio,unit:$0.unit)};guard ingredients.allSatisfy({$0.quantity.isFinite})else{throw Invalid.input};return Recipe(title:r.title,servings:servings,ingredients:ingredients)}
do{let args=CommandLine.arguments;if args.count==2 && args[1]=="--self-test"{let r=Recipe(title:"Soup",servings:4,ingredients:[Ingredient(name:"Water",quantity:1.5,unit:"litre")]);let s=try scale(r,6);precondition(s.ingredients[0].quantity==2.25);do{_ = try scale(r,0);fatalError("Accepted zero servings")}catch Invalid.input{};print("Fractional scaling, output servings and invalid-input checks passed")}else{guard args.count==3,let n=Double(args[2])else{throw Invalid.input};let r=try JSONDecoder().decode(Recipe.self,from:Data(contentsOf:URL(fileURLWithPath:args[1])));let encoder=JSONEncoder();encoder.outputFormatting=[.prettyPrinted,.sortedKeys];let data=try encoder.encode(scale(r,n));print(String(decoding:data,as:UTF8.self))}}catch{fputs("Usage: recipe-kit recipe.json target-servings (positive finite values required)\n",stderr);exit(1)}
